"""Both mailbox entrypoints distinguish mismatch from unqualified verifier state."""

from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
from pathlib import Path
from types import ModuleType, SimpleNamespace
from typing import Any
from unittest.mock import Mock

import pytest

ROOT = Path(__file__).parents[1] / "src/ops_deploy/services"
# Synthetic password only: verifiers were generated by real owned Dovecot2.3.21.
PASSWORD = "owned-verifier-fixture-password"
VERIFIERS = json.loads((Path(__file__).parent / "fixtures/mail-sha512-crypt-owned.json").read_text())


class Cursor:
    def __init__(self, stored: str) -> None:
        self.stored = stored
        self.rows: list[tuple[Any, ...]] = []
        self.writes: list[str] = []

    def __enter__(self) -> Cursor:
        return self

    def __exit__(self, *args: object) -> None:
        pass

    def execute(self, statement: str, parameters: object = None) -> None:
        if statement.startswith("SELECT id FROM mail_domains"):
            self.rows = [(1,)]
        elif statement.startswith("SELECT id, password, active FROM mail_users"):
            self.rows = [(2, self.stored, True)]
        elif statement.startswith(("INSERT", "UPDATE", "DELETE")):
            self.writes.append(statement)

    def fetchall(self) -> list[tuple[Any, ...]]:
        return self.rows


class Connection:
    def __init__(self, stored: str) -> None:
        self.cur = Cursor(stored)

    def __enter__(self) -> Connection:
        return self

    def __exit__(self, *args: object) -> None:
        pass

    def set_session(self, **kwargs: object) -> None:
        pass

    def cursor(self) -> Cursor:
        return self.cur


def entrypoint(monkeypatch: pytest.MonkeyPatch, kind: str, stored: str) -> tuple[ModuleType, Connection]:
    db = Connection(stored)

    class PsycopgFixture(ModuleType):
        connect = Mock(return_value=db)
        sql = SimpleNamespace()

    psycopg = PsycopgFixture("psycopg2")
    monkeypatch.setitem(sys.modules, "psycopg2", psycopg)
    resource = (
        "mail_monitoring/files/mailbox.py" if kind == "monitor" else "mail_backend/files/mail_backend_database.py"
    )
    spec = importlib.util.spec_from_file_location("owned_mail_" + kind, ROOT / resource)
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module, db


def invoke(module: ModuleType, kind: str, stored: str, apply: bool) -> bool:
    if kind == "core":
        return not bool(module.password_matches(stored, PASSWORD))
    return bool(
        module.reconcile(
            {
                "password": PASSWORD,
                "address": "owned@example.test",
                "database": "owned",
                "schema_mode": "legacy",
                "active": True,
            },
            apply,
        )
    )


@pytest.mark.parametrize("kind", ["core", "monitor"])
@pytest.mark.parametrize("record", VERIFIERS)
@pytest.mark.parametrize("status", [0, 75])
def test_real_native_hash_forms_use_known_match_or_mismatch(
    monkeypatch: pytest.MonkeyPatch,
    kind: str,
    record: dict[str, Any],
    status: int,
) -> None:
    module, db = entrypoint(monkeypatch, kind, record["stored"])
    native = Mock(return_value=subprocess.CompletedProcess([], status, "", ""))
    monkeypatch.setattr(module.subprocess, "run", native)
    assert invoke(module, kind, record["stored"], False) == (status == 75)
    assert not db.cur.writes
    command = native.call_args.args[0]
    assert command[:4] == ["doveadm", "-O", "pw", "-t"]
    assert PASSWORD not in " ".join(command)
    assert native.call_args.kwargs["input"] == PASSWORD + "\n"


@pytest.mark.parametrize("kind", ["core", "monitor"])
@pytest.mark.parametrize("apply", [False, True])
@pytest.mark.parametrize(
    "problem",
    [
        "short",
        "unsupported",
        "rounds-zero",
        "rounds-leading-zero",
        "rounds-below",
        "rounds-above",
        "rounds-huge",
        "bad-padding",
        "bad-salt",
    ],
)
def test_native_invalid_mismatch_status_cannot_authorize_rotation(
    monkeypatch: pytest.MonkeyPatch,
    kind: str,
    apply: bool,
    problem: str,
) -> None:
    stored = VERIFIERS[0]["stored"]
    salt, digest = stored.removeprefix("{SHA512-CRYPT}$6$").rsplit("$", 1)
    broken = {
        "short": "{SHA512-CRYPT}$6$broken",
        "unsupported": stored.replace("{SHA512-CRYPT}", "{UNKNOWN}"),
        "rounds-zero": "{SHA512-CRYPT}$6$rounds=0$" + salt + "$" + digest,
        "rounds-leading-zero": "{SHA512-CRYPT}$6$rounds=01000$" + salt + "$" + digest,
        "rounds-below": "{SHA512-CRYPT}$6$rounds=999$" + salt + "$" + digest,
        "rounds-above": "{SHA512-CRYPT}$6$rounds=1000000000$" + salt + "$" + digest,
        "rounds-huge": "{SHA512-CRYPT}$6$rounds=" + "9" * 100 + "$" + salt + "$" + digest,
        "bad-padding": stored[:-1] + "Z",
        "bad-salt": "{SHA512-CRYPT}$6$invalid salt$" + digest,
    }[problem]
    module, db = entrypoint(monkeypatch, kind, broken)
    # Native Dovecot also returns75 for these invalid hashes. The entrypoint
    # must reject the stored state before relying on that ambiguous status.
    native = Mock(return_value=subprocess.CompletedProcess([], 75, "", ""))
    monkeypatch.setattr(module.subprocess, "run", native)
    with pytest.raises(ValueError, match="unsupported or malformed"):
        invoke(module, kind, broken, apply)
    native.assert_not_called()
    assert db.cur.stored == broken
    assert not db.cur.writes


@pytest.mark.parametrize("kind", ["core", "monitor"])
@pytest.mark.parametrize("apply", [False, True])
@pytest.mark.parametrize("failure", ["exit", "timeout", "missing"])
def test_failed_native_tool_preserves_stored_row(
    monkeypatch: pytest.MonkeyPatch,
    kind: str,
    apply: bool,
    failure: str,
) -> None:
    stored = VERIFIERS[0]["stored"]
    module, db = entrypoint(monkeypatch, kind, stored)
    native = Mock(return_value=subprocess.CompletedProcess([], 1, "", ""))
    if failure == "timeout":
        native.side_effect = subprocess.TimeoutExpired("doveadm", 30)
    elif failure == "missing":
        native.side_effect = FileNotFoundError("owned missing native tool")
    monkeypatch.setattr(module.subprocess, "run", native)
    with pytest.raises((ValueError, subprocess.TimeoutExpired, FileNotFoundError)):
        invoke(module, kind, stored, apply)
    assert db.cur.stored == stored
    assert not db.cur.writes


class Statement(str):
    """psycopg2.sql stand-in: composed statements stay inspectable text."""

    def format(self, *args: object) -> Statement:  # type: ignore[override]
        return Statement(" ".join([str(self), *map(str, args)]))

    def __add__(self, other: object) -> Statement:
        return Statement(str(self) + str(other))

    def join(self, items: object) -> Statement:
        return Statement(str.join(self, map(str, items)))  # type: ignore[call-overload]


class CoreCursor:
    """Answers every query the legacy core reconcile issues on a current catalog."""

    def __init__(self, stored: str) -> None:
        self.stored = stored
        self.rows: list[tuple[Any, ...]] = []
        self.writes: list[tuple[str, object]] = []

    def __enter__(self) -> CoreCursor:
        return self

    def __exit__(self, *args: object) -> None:
        pass

    def execute(self, statement: object, parameters: object = None) -> None:
        text = str(statement)
        self.rows = []
        if text.startswith(("INSERT", "UPDATE", "DELETE")):
            self.writes.append((text, parameters))
        elif text.startswith("SELECT pg_get_viewdef"):
            self.rows = [("owned current definition",)]
        elif text.startswith(
            (
                "SELECT to_regclass",
                "SELECT has_database_privilege",
                "SELECT 1 FROM mail_aliases",
                "SELECT id FROM mail_domains",
            )
        ):
            self.rows = [(1,)]
        elif text.startswith("SELECT u.id,u.password,u.active FROM mail_users"):
            self.rows = [(2, self.stored, True)]

    def fetchone(self) -> tuple[Any, ...] | None:
        return self.rows[0] if self.rows else None

    def fetchall(self) -> list[tuple[Any, ...]]:
        return self.rows


def core_reconcile(
    monkeypatch: pytest.MonkeyPatch, stored: str, native: Mock
) -> tuple[ModuleType, CoreCursor, Mock, dict[str, Any]]:
    from ops_deploy.core.secrets import SecretRef, SecretValues
    from ops_deploy.services.mail_backend import MailBackendConfig
    from ops_deploy.services.mail_backend.render import render_role

    cursor = CoreCursor(stored)
    connection = Mock()
    connection.cursor.return_value = cursor
    psycopg = ModuleType("psycopg2")
    psycopg.connect = Mock(return_value=connection)  # type: ignore[attr-defined]
    psycopg.sql = SimpleNamespace(SQL=Statement, Identifier=lambda *parts: ".".join(parts))  # type: ignore[attr-defined]
    monkeypatch.setitem(sys.modules, "psycopg2", psycopg)
    spec = importlib.util.spec_from_file_location(
        "owned_core_reconcile", ROOT / "mail_backend/files/mail_backend_database.py"
    )
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    monkeypatch.setattr(module.subprocess, "run", native)
    cfg = MailBackendConfig(domains=("example.test",), initial_user="owned", initial_user_domain="example.test")
    secrets = SecretValues(SecretRef("owned.yml"), {"postgres_password": "owned", "relay_password": "owned"})
    request = {
        "config": cfg.model_dump(mode="json", exclude={"secrets"}),
        "schema_sql": render_role("schema.sql.j2", cfg, secrets),
        "initial_password": PASSWORD,
    }
    return module, cursor, connection, request


@pytest.mark.parametrize("apply", [False, True])
@pytest.mark.parametrize("problem", ["malformed", "exit", "timeout", "missing"])
def test_core_reconcile_unqualified_initial_mailbox_never_rotates(
    monkeypatch: pytest.MonkeyPatch, apply: bool, problem: str
) -> None:
    stored = "{SHA512-CRYPT}$6$broken" if problem == "malformed" else VERIFIERS[0]["stored"]
    native = Mock(return_value=subprocess.CompletedProcess([], 1 if problem == "exit" else 75, "", ""))
    if problem == "timeout":
        native.side_effect = subprocess.TimeoutExpired("doveadm", 30)
    elif problem == "missing":
        native.side_effect = FileNotFoundError("owned missing native tool")
    module, cursor, connection, request = core_reconcile(monkeypatch, stored, native)
    with pytest.raises((ValueError, subprocess.TimeoutExpired, FileNotFoundError)):
        module.reconcile(request, apply)
    assert all("-s" not in call.args[0] for call in native.call_args_list), "no new hash generated"
    assert not [text for text, _ in cursor.writes if "mail_users" in text]
    connection.commit.assert_not_called()
    connection.rollback.assert_called()
    connection.close.assert_called_once()


@pytest.mark.parametrize("status", [0, 75])
def test_core_reconcile_apply_keeps_matching_hash_and_replaces_known_mismatch(
    monkeypatch: pytest.MonkeyPatch, status: int
) -> None:
    stored = VERIFIERS[0]["stored"]
    generated = VERIFIERS[-1]["stored"]

    def native(command: list[str], **kwargs: Any) -> subprocess.CompletedProcess[str]:
        if command[3] == "-s":
            return subprocess.CompletedProcess(command, 0, generated + "\n", "")
        return subprocess.CompletedProcess(command, 0 if command[4] == generated else status, "", "")

    module, cursor, connection, request = core_reconcile(monkeypatch, stored, Mock(side_effect=native))
    changed, checks = module.reconcile(request, True)
    assert checks == 6
    updates = [(text, parameters) for text, parameters in cursor.writes if "mail_users" in text]
    if status == 0:
        assert not changed
        assert not updates
    else:
        assert changed
        assert updates == [("UPDATE mail_users SET password=%s WHERE id=%s", (generated, 2))]
    connection.commit.assert_called_once()
